std::stringstream ss("DataXEnd");
char lookahead;

// Read 'D', 'a', 't', 'a'
std::string result;
ss >> result; // result = "Data"

// Read 'X'
if (ss.get(lookahead)) {
    // If 'X' is the delimiter, put it back
    if (lookahead == 'X') {
        ss.unget();
    }
}

// Check stream state after unget()
// unget() may set failbit if the buffer is full
if (ss.fail() && !ss.eof()) {
    // Clear only failbit, keeping others (like eof)
    ss.clear(ss.rdstate() & ~std::ios::failbit);
}

